package com.dbu.reservation.infrastructure.repository;
import com.dbu.reservation.domain.model.*;import com.dbu.reservation.domain.repository.ReservationRepository;import com.dbu.reservation.infrastructure.database.DatabaseConnection;import java.sql.*;import java.time.*;import java.util.*;
public final class JdbcReservationRepository implements ReservationRepository {
 public void request(long uid,long rid,LocalDate date,LocalTime start,LocalTime end,int people,String purpose,String description){String q="INSERT INTO reservations(user_id,room_id,reservation_date,start_time,end_time,participant_count,purpose,description,status) VALUES(?,?,?,?,?,?,?,?,'PENDING')";try(Connection c=DatabaseConnection.open()){c.setAutoCommit(false);try{try(PreparedStatement lock=c.prepareStatement("SELECT room_id FROM rooms WHERE room_id=? AND status='ACTIVE' FOR UPDATE")){lock.setLong(1,rid);try(ResultSet r=lock.executeQuery()){if(!r.next())throw new IllegalArgumentException("Room is inactive or unavailable.");}}try(PreparedStatement check=c.prepareStatement("SELECT 1 FROM reservations WHERE room_id=? AND reservation_date=? AND status='APPROVED' AND ?<end_time AND ?>start_time LIMIT 1")){check.setLong(1,rid);check.setDate(2,java.sql.Date.valueOf(date));check.setTime(3,Time.valueOf(start));check.setTime(4,Time.valueOf(end));try(ResultSet r=check.executeQuery()){if(r.next())throw new IllegalArgumentException("Room already has an approved reservation in that time range.");}}try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,uid);p.setLong(2,rid);p.setDate(3,java.sql.Date.valueOf(date));p.setTime(4,Time.valueOf(start));p.setTime(5,Time.valueOf(end));p.setInt(6,people);p.setString(7,purpose);p.setString(8,description);p.executeUpdate();}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(SQLException e){throw new IllegalStateException("Could not save reservation request.",e);}}
 public List<Reservation> findByUser(long uid){return query(" AND r.user_id=?",uid);}public List<Reservation> findPending(){return query(" AND r.status='PENDING'",null);}
 private List<Reservation> query(String filter,Long uid){String q="SELECT r.reservation_id,u.full_name,rm.room_name,r.reservation_date,r.start_time,r.end_time,r.participant_count,r.purpose,r.status,r.rejection_reason FROM reservations r JOIN users u ON u.user_id=r.user_id JOIN rooms rm ON rm.room_id=r.room_id WHERE 1=1"+filter+" ORDER BY r.created_at DESC";List<Reservation> out=new ArrayList<>();try(Connection c=DatabaseConnection.open();PreparedStatement p=c.prepareStatement(q)){if(uid!=null)p.setLong(1,uid);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Reservation(r.getLong(1),r.getString(2),r.getString(3),r.getDate(4).toLocalDate(),r.getTime(5).toLocalTime(),r.getTime(6).toLocalTime(),r.getInt(7),r.getString(8),ReservationStatus.valueOf(r.getString(9)),r.getString(10)));}return out;}catch(SQLException e){throw new IllegalStateException("Could not load reservations.",e);}}
 public void decide(long id,long admin,boolean approve,String reason){try(Connection c=DatabaseConnection.open()){c.setAutoCommit(false);try{long room;LocalDate date;LocalTime start,end;try(PreparedStatement p=c.prepareStatement("SELECT room_id,reservation_date,start_time,end_time,status,user_id FROM reservations WHERE reservation_id=? FOR UPDATE")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()||!"PENDING".equals(r.getString(5)))throw new IllegalArgumentException("Request is no longer pending.");room=r.getLong(1);date=r.getDate(2).toLocalDate();start=r.getTime(3).toLocalTime();end=r.getTime(4).toLocalTime();}}
 try(PreparedStatement p=c.prepareStatement("SELECT room_id FROM rooms WHERE room_id=? FOR UPDATE")){p.setLong(1,room);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Room no longer exists.");}}
 if(approve){try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM reservations WHERE room_id=? AND reservation_date=? AND status='APPROVED' AND ?<end_time AND ?>start_time LIMIT 1")){p.setLong(1,room);p.setDate(2,java.sql.Date.valueOf(date));p.setTime(3,Time.valueOf(start));p.setTime(4,Time.valueOf(end));try(ResultSet r=p.executeQuery()){if(r.next())throw new IllegalArgumentException("Another approved reservation conflicts with this time.");}}}
 String status=approve?"APPROVED":"REJECTED";try(PreparedStatement p=c.prepareStatement("UPDATE reservations SET status=?,rejection_reason=?,processed_by=?,processed_at=CURRENT_TIMESTAMP WHERE reservation_id=?")){p.setString(1,status);p.setString(2,approve?null:reason);p.setLong(3,admin);p.setLong(4,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO notifications(user_id,message) SELECT user_id,? FROM reservations WHERE reservation_id=?")){p.setString(1,"Reservation #"+id+" was "+status.toLowerCase()+(approve?".":": "+reason));p.setLong(2,id);p.executeUpdate();}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("Could not process approval.",e);}}
}
